function assertOrderTextsAlignWithDomain(): void {
  for (const g of GIANT_IDS) {
    const n = GIANT_ORDER_TEXTS[g].length;
    const expected = GIANT_ORDER_COUNT[g];
    if (n !== expected) {
      throw new Error(
        `GIANT_ORDER_TEXTS[${g}] has ${n} entries, GIANT_ORDER_COUNT expects ${expected}`,
      );
    }
  }
}

assertOrderTextsAlignWithDomain();

/** Текст заказа по миссии (индекс из {@link MissionRef}). */
export function getGiantOrderText(mission: MissionRef): string {
  const list = GIANT_ORDER_TEXTS[mission.giantId];
  return list[mission.orderIndex];
}

/** Все строки заказов гиганта (копия для UI). */
export function getGiantOrderTexts(giantId: GiantId): readonly string[] {
  return GIANT_ORDER_TEXTS[giantId];
}
