import type { CourierId, LevelDefinition, MissionRef } from '../../domain';
import { GameSession } from './GameSession';

/** Старт сессии с миссией (обёртка над {@link GameSession.start}). */
export function createGameSessionForMission(
  level: LevelDefinition,
  courierId: CourierId,
  mission: MissionRef,
): GameSession {
  return GameSession.start(level, courierId, { mission });
}
