/**
 * Префикс ключей персистентности (tech-spec §10, §16.3).
 * Единый namespace для localStorage и VK Storage.
 */
export const STORAGE_NAMESPACE = 'delivery_vk_app';

export const STORAGE_RECORD_KEYS = {
  onboarding_complete: 'onboarding_complete',
  selected_courier_id: 'selected_courier_id',
} as const;

export type StorageRecordKey = keyof typeof STORAGE_RECORD_KEYS;

export function toStorageStringKey(recordKey: StorageRecordKey): string {
  return `${STORAGE_NAMESPACE}:${STORAGE_RECORD_KEYS[recordKey]}`;
}
