import type { CSSProperties } from 'react';
import { t } from '../../i18n';
import commonBackground from '../../infrastructure/assets/Images/commonBackground.png';
import commonHeaderBackground from '../../infrastructure/assets/Images/commonHeaderBackground.png';
import rewardCardDefault from '../../infrastructure/assets/Images/rewardCardBackground_default.png';
import rewardCardSpecial from '../../infrastructure/assets/Images/rewardCardBackground_special.png';
import clockIcon from '../../infrastructure/assets/Images/clockIcon.png';
import coinIcon from '../../infrastructure/assets/Images/coinIcon.png';
import lobbyInteractArrow from '../../infrastructure/assets/Images/lobbyInteractArrow.png';

type TaskDef = {
  id: string;
  urgent: boolean;
  titleKey: 'game.tasks.mona' | 'game.tasks.yeti' | 'game.tasks.factor' | 'game.tasks.swami';
  reward: string;
};

const TASK_DEFS: readonly TaskDef[] = [
  { id: 't1', urgent: true, titleKey: 'game.tasks.mona', reward: '+30' },
  { id: 't2', urgent: true, titleKey: 'game.tasks.yeti', reward: '+30' },
  { id: 't3', urgent: false, titleKey: 'game.tasks.factor', reward: '+10' },
  { id: 't4', urgent: false, titleKey: 'game.tasks.swami', reward: '+15' },
];

const root: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  textAlign: 'center',
  color: '#3a145c',
  backgroundImage: `url(${commonBackground})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  backgroundRepeat: 'no-repeat',
};

const headerStrip: CSSProperties = {
  width: '100%',
  flexShrink: 0,
  marginTop: 3,
  paddingTop: 'max(8px, env(safe-area-inset-top))',
  backgroundImage: `url(${commonHeaderBackground})`,
  backgroundRepeat: 'no-repeat',
  backgroundSize: '100% 100%',
  backgroundPosition: 'center top',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  minHeight: 52,
  paddingBottom: 12,
  paddingLeft: 16,
  paddingRight: 16,
  boxSizing: 'border-box',
};

const titleOnHeader: CSSProperties = {
  margin: 0,
  fontSize: 22,
  fontWeight: 900,
  color: '#3a145c',
  textShadow: '0 1px 0 rgba(255,255,255,0.6)',
};

const body: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  padding: '10px 12px 8px',
  boxSizing: 'border-box',
};

const list: CSSProperties = {
  flex: 1,
  minHeight: 0,
  overflowY: 'auto',
  paddingBottom: 8,
  display: 'flex',
  flexDirection: 'column',
  gap: 12,
  alignItems: 'center',
};

const cardBase: CSSProperties = {
  width: '100%',
  maxWidth: 420,
  minHeight: 86,
  boxSizing: 'border-box',
  padding: '12px 14px 12px 44px',
  borderRadius: 18,
  position: 'relative',
  color: '#fff',
  fontWeight: 800,
  fontSize: 15,
  lineHeight: 1.25,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: 12,
  border: '3px solid rgba(0,0,0,0.2)',
};

const rewardBox: CSSProperties = {
  flexShrink: 0,
  minWidth: 92,
  padding: '8px 10px',
  borderRadius: 14,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 6,
  fontWeight: 900,
  fontSize: 15,
};

export function GameDeliveriesScreen() {
  const scrollHint = () => {
    const el = document.getElementById('game-deliveries-list');
    el?.scrollBy({ top: 120, behavior: 'smooth' });
  };

  return (
    <div style={root}>
      <header style={headerStrip}>
        <h2 style={titleOnHeader}>{t('game.tasks.title')}</h2>
      </header>
      <div style={body}>
        <div id="game-deliveries-list" style={list}>
          {TASK_DEFS.map((task) => (
            <div
              key={task.id}
              style={{
                ...cardBase,
                backgroundImage: `url(${task.urgent ? rewardCardSpecial : rewardCardDefault})`,
                backgroundSize: '100% 100%',
              }}
            >
              {task.urgent ? (
                <img
                  src={clockIcon}
                  alt=""
                  width={36}
                  height={36}
                  style={{ position: 'absolute', left: 8, top: 8, objectFit: 'contain' }}
                />
              ) : null}
              <div style={{ textAlign: 'left' }}>{t(task.titleKey)}</div>
              <div
                style={{
                  ...rewardBox,
                  background: task.urgent ? 'rgba(80, 30, 10, 0.55)' : 'rgba(50, 10, 80, 0.55)',
                }}
              >
                {task.reward}
                <img src={coinIcon} alt="" width={26} height={26} style={{ objectFit: 'contain' }} />
              </div>
            </div>
          ))}
        </div>
        <div style={{ display: 'flex', justifyContent: 'center', paddingBottom: 4 }}>
          <button
            type="button"
            onClick={scrollHint}
            aria-label={t('game.tasks.scrollDown')}
            style={{
              border: 'none',
              background: 'transparent',
              cursor: 'pointer',
              padding: 4,
            }}
          >
            <img src={lobbyInteractArrow} alt="" width={32} height={32} style={{ transform: 'rotate(90deg)' }} />
          </button>
        </div>
      </div>
    </div>
  );
}
