import { useEffect, useMemo, useReducer, useRef } from 'react';
import { Link, Navigate, useLocation } from 'react-router-dom';
import { DEV_FLIGHT_LEVEL } from '../../content';
import {
  createGameSessionForMission,
  GameSession,
  FlightRunController,
  deriveGameplayPhase,
} from '../../application';
import type { MissionRef } from '../../domain';
import {
  getStrikeDamageVisualStage,
  isGiantId,
  isTerminal,
  validateMissionRef,
} from '../../domain';
import { t } from '../../i18n';
import { useAppStore } from '../store/appStore';

function missionFromLocationState(state: unknown): MissionRef | null {
  if (state == null || typeof state !== 'object') {
    return null;
  }
  const raw = (state as { mission?: unknown }).mission;
  if (raw == null || typeof raw !== 'object') {
    return null;
  }
  const rec = raw as { giantId?: unknown; orderIndex?: unknown };
  if (typeof rec.giantId !== 'string' || typeof rec.orderIndex !== 'number') {
    return null;
  }
  if (!isGiantId(rec.giantId) || !Number.isInteger(rec.orderIndex)) {
    return null;
  }
  const mission: MissionRef = { giantId: rec.giantId, orderIndex: rec.orderIndex };
  return validateMissionRef(mission).ok ? mission : null;
}

export function GameplayDevScreen() {
  const courierId = useAppStore((s) => s.selectedCourierId);
  const location = useLocation();
  const mission = useMemo(() => missionFromLocationState(location.state), [location.state]);

  const missionMismatch =
    mission != null && mission.giantId !== DEV_FLIGHT_LEVEL.giantId;

  const [, rerender] = useReducer((x: number) => x + 1, 0);
  const sessionRef = useRef<GameSession | null>(null);
  const controllerRef = useRef<FlightRunController | null>(null);
  const rafRef = useRef(0);
  const lastTsRef = useRef(0);

  const missionKey =
    mission == null ? 'none' : `${mission.giantId}:${mission.orderIndex}`;

  useEffect(() => {
    if (courierId == null || missionMismatch) {
      return;
    }
    const session =
      mission != null
        ? createGameSessionForMission(DEV_FLIGHT_LEVEL, courierId, mission)
        : GameSession.start(DEV_FLIGHT_LEVEL, courierId);
    const controller = new FlightRunController(session);
    sessionRef.current = session;
    controllerRef.current = controller;
    lastTsRef.current = performance.now();
    rerender();

    const loop = (now: number) => {
      const s = sessionRef.current;
      const c = controllerRef.current;
      if (!s || !c) {
        return;
      }
      const prev = lastTsRef.current;
      lastTsRef.current = now;
      const dt = Math.min(0.25, Math.max(0, (now - prev) / 1000));
      c.tickFrame(dt);
      rerender();
      if (!isTerminal(s.getDeliveryRun())) {
        rafRef.current = requestAnimationFrame(loop);
      }
    };
    rafRef.current = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(rafRef.current);
      sessionRef.current?.abort();
      sessionRef.current = null;
      controllerRef.current = null;
    };
  }, [courierId, missionMismatch, missionKey, mission]);

  if (courierId == null) {
    return <Navigate to="/courier" replace />;
  }

  if (missionMismatch) {
    return (
      <div style={{ padding: 24 }}>
        <p>{t('shell.play.missionMismatch')}</p>
        <p>
          <Link to="/home">{t('shell.play.back')}</Link>
        </p>
      </div>
    );
  }

  const session = sessionRef.current;
  if (session == null) {
    return (
      <div style={{ padding: 24 }}>
        <p>{t('shell.splash.loading')}</p>
      </div>
    );
  }

  const controller = controllerRef.current;
  const progress = controller?.getProgress();
  const run = session.getDeliveryRun();
  const phase = deriveGameplayPhase(session);
  const visualStage = getStrikeDamageVisualStage(run);
  const terminal = isTerminal(run);
  const orderLine = session.getCurrentOrderText();

  const bump = () => rerender();

  return (
    <div style={{ padding: 24, maxWidth: 520 }}>
      <p>
        <Link to="/home">{t('shell.play.back')}</Link>
      </p>
      <h1>{t('shell.play.title')}</h1>
      <p>
        <strong>{courierId}</strong> · {DEV_FLIGHT_LEVEL.id}
      </p>
      {orderLine != null ? (
        <p>
          <em>{t('shell.play.orderInRun')}:</em> {orderLine}
        </p>
      ) : null}
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
        <button
          type="button"
          disabled={terminal}
          onClick={() => {
            session.setPaused(!session.isPaused());
            bump();
          }}
        >
          {session.isPaused() ? t('shell.play.resume') : t('shell.play.pause')}
        </button>
        <button
          type="button"
          disabled={terminal || session.isShieldActive()}
          onClick={() => {
            session.registerObstacleCollision();
            bump();
          }}
        >
          {t('shell.play.testHit')}
        </button>
        <button
          type="button"
          disabled={terminal || progress == null || progress.distanceFromFinishS > 0.001}
          onClick={() => {
            session.completeLevel();
            bump();
          }}
        >
          {t('shell.play.complete')}
        </button>
      </div>
      {phase === 'minigame_required' ? (
        <p role="status" style={{ color: 'crimson' }}>
          {t('shell.play.minigameBanner')}
        </p>
      ) : null}
      {terminal ? (
        <p role="status">{t('shell.play.finished')}</p>
      ) : null}
      <dl style={{ display: 'grid', gridTemplateColumns: '1fr auto', gap: '4px 16px' }}>
        <dt>{t('shell.play.hudTime')}</dt>
        <dd>{session.getWorldTimeSec().toFixed(2)}</dd>
        <dt>{t('shell.play.hudDistance')}</dt>
        <dd>{progress != null ? progress.distanceAlongRouteS.toFixed(1) : '—'}</dd>
        <dt>{t('shell.play.hudFinish')}</dt>
        <dd>{progress != null ? progress.distanceFromFinishS.toFixed(1) : '—'}</dd>
        <dt>{t('shell.play.hudStrikes')}</dt>
        <dd>{run.kind === 'flying' ? run.strikesTowardMinigame : '—'}</dd>
        <dt>{t('shell.play.hudPhase')}</dt>
        <dd>{phase}</dd>
        <dt>{t('shell.play.hudShield')}</dt>
        <dd>{session.isShieldActive() ? t('shell.play.yes') : t('shell.play.no')}</dd>
        <dt>{t('shell.play.hudSpeed')}</dt>
        <dd>{session.isSpeedBoostActive() ? t('shell.play.yes') : t('shell.play.no')}</dd>
        <dt>{t('shell.play.hudShrink')}</dt>
        <dd>{session.isResizeShrinkActive() ? t('shell.play.yes') : t('shell.play.no')}</dd>
        <dt>visualDamageStage</dt>
        <dd>{visualStage === null ? '—' : String(visualStage)}</dd>
      </dl>
    </div>
  );
}
