import {
  BOOSTER_EFFECT_DURATION_SEC,
  BOOSTER_SHRINK_HITBOX_MULTIPLIER,
  BOOSTER_SPEED_MULTIPLIER,
  applyCountedObstacleCollision,
  abortDeliveryRun,
  completeDeliveryRun,
  createInitialDeliveryRun,
  getCourierForwardSpeedMultiplier,
  getMinigamesForCourier,
  isMinigameAllowedForCourier,
  resolveMinigameLoss,
  resolveMinigameWin,
  isTerminal,
  validateLevelDefinition,
  validateMissionRef,
} from '../../domain';
import type {
  CourierId,
  DeliveryRunState,
  LevelDefinition,
  MinigameId,
  MissionRef,
} from '../../domain';
import { getGiantOrderText } from '../../content';

export type ObstacleCollisionReport = {
  /**
   * Активен буст «Защита»: удар поглощён, {@link DeliveryRunState} не меняется —
   * strikes к мини-игре не растут (tech-spec §7.4, вариант без инкремента).
   */
  blockedByShield: boolean;
  /** Поглощено зарядом «доп. жизнь»: strikes не растут (GDD: доп. жизни). */
  consumedExtraLife: boolean;
  openedMinigame: boolean;
};

export type GameSessionStartOptions = {
  /** Если задано — проверяется и связывается с текстом заказа из `src/content`. */
  mission?: MissionRef;
};

/**
 * Фасад одной игровой сессии: уровень, курьер, попытка доставки, тайминги бустеров (GDD).
 * Каталог мини-игр — из домена по `courierId`.
 * Без React; вызывается из цикла симуляции или тестов.
 */
export class GameSession {
  private worldTimeSec = 0;
  private paused = false;

  /** Момент времени мира (сек), до которого действует эффект (не включительно). */
  private shieldEndsAt: number | null = null;
  private speedEndsAt: number | null = null;
  private shrinkEndsAt: number | null = null;

  /** Заряды «доп. жизни»: поглощают одно засчитываемое столкновение каждый. */
  private extraLifeCharges = 0;

  private deliveryRun: DeliveryRunState;

  readonly level: LevelDefinition;

  readonly courierId: CourierId;

  /** Миссия (гигант + индекс заказа); может быть null для свободного полёта / тестов. */
  readonly mission: MissionRef | null;

  private constructor(
    level: LevelDefinition,
    courierId: CourierId,
    run: DeliveryRunState,
    mission: MissionRef | null,
  ) {
    this.level = level;
    this.courierId = courierId;
    this.deliveryRun = run;
    this.mission = mission;
  }

  /**
   * Старт сессии. Бросает, если уровень не проходит {@link validateLevelDefinition}.
   * Опционально — {@link MissionRef}: должен быть валиден и `mission.giantId === level.giantId`.
   */
  static start(
    level: LevelDefinition,
    courierId: CourierId,
    options?: GameSessionStartOptions,
  ): GameSession {
    const v = validateLevelDefinition(level);
    if (!v.ok) {
      throw new Error(`Invalid level: ${v.errors.join('; ')}`);
    }

    const mission = options?.mission ?? null;
    if (mission != null) {
      const mv = validateMissionRef(mission);
      if (!mv.ok) {
        throw new Error(`Invalid mission: ${mv.errors.join('; ')}`);
      }
      if (mission.giantId !== level.giantId) {
        throw new Error(
          `mission.giantId (${mission.giantId}) must match level.giantId (${level.giantId})`,
        );
      }
    }

    return new GameSession(level, courierId, createInitialDeliveryRun(), mission);
  }

  /** Допустимые мини-игры для текущего курьера (GDD). */
  getMinigameCatalog(): readonly MinigameId[] {
    return getMinigamesForCourier(this.courierId);
  }

  /** Перед запуском сцены мини-игры — убедиться, что выбор из каталога курьера. */
  validateMinigameChoice(id: MinigameId): void {
    if (!isMinigameAllowedForCourier(this.courierId, id)) {
      throw new Error(`Minigame "${id}" is not allowed for courier "${this.courierId}"`);
    }
  }

  /** Текст текущего заказа из контента; без миссии — null. */
  getCurrentOrderText(): string | null {
    if (this.mission == null) {
      return null;
    }
    return getGiantOrderText(this.mission);
  }

  /** Состояние «нужна мини-игра» после третьего столкновения. */
  isMinigameGateActive(): boolean {
    return this.deliveryRun.kind === 'minigame_required';
  }

  getWorldTimeSec(): number {
    return this.worldTimeSec;
  }

  getDeliveryRun(): DeliveryRunState {
    return this.deliveryRun;
  }

  /** Пауза: время мира и таймеры бустеров не идут (tech-spec §4 — политика для QA). */
  setPaused(paused: boolean): void {
    this.paused = paused;
  }

  isPaused(): boolean {
    return this.paused;
  }

  isShieldActive(): boolean {
    return this.shieldEndsAt != null && this.worldTimeSec < this.shieldEndsAt;
  }

  isSpeedBoostActive(): boolean {
    return this.speedEndsAt != null && this.worldTimeSec < this.speedEndsAt;
  }

  isResizeShrinkActive(): boolean {
    return this.shrinkEndsAt != null && this.worldTimeSec < this.shrinkEndsAt;
  }

  getExtraLifeCharges(): number {
    return this.extraLifeCharges;
  }

  /**
   * Множитель скорости «вперёд»: курьер (GDD) × ускоритель (×1,3), если активен.
   * Итоговая скорость в симуляции: `level.baseForwardSpeed * это значение`.
   */
  getEffectiveForwardSpeedMultiplier(): number {
    const courier = getCourierForwardSpeedMultiplier(this.courierId);
    return courier * (this.isSpeedBoostActive() ? BOOSTER_SPEED_MULTIPLIER : 1);
  }

  /** Множитель к радиусу/хитбоксу от бустера «уменьшение»; иначе 1. */
  getResizeShrinkHitboxMultiplier(): number {
    return this.isResizeShrinkActive() ? BOOSTER_SHRINK_HITBOX_MULTIPLIER : 1;
  }

  /**
   * Продвижение игрового времени (сек). Влияет на истечение бустеров по таймеру.
   * При паузе — no-op.
   */
  advanceWorldTime(deltaSec: number): void {
    if (this.paused) {
      return;
    }
    if (!Number.isFinite(deltaSec) || deltaSec < 0) {
      throw new Error('advanceWorldTime: deltaSec must be a non-negative finite number');
    }
    this.worldTimeSec += deltaSec;
  }

  private mergeTimedEnd(currentEnd: number | null, durationSec: number): number {
    const end = this.worldTimeSec + durationSec;
    return currentEnd != null ? Math.max(currentEnd, end) : end;
  }

  /** Бустеры и заряды жизней недоступны после завершения попытки (успех / провал / выход). */
  private assertNotTerminalForBoosterAction(action: string): void {
    if (isTerminal(this.deliveryRun)) {
      throw new Error(
        `GameSession: ${action} is not allowed: delivery run is terminal (outcome already settled)`,
      );
    }
  }

  /**
   * «Защита»: пока активна, каждый удар по препятствию **поглощается** —
   * счётчик столкновений к мини-игре не увеличивается (как «blocked hit» без strike).
   * Повторная активация продлевает до max(текущий конец, now + duration).
   */
  activateShield(durationSec: number = BOOSTER_EFFECT_DURATION_SEC): void {
    this.assertNotTerminalForBoosterAction('activateShield');
    if (!Number.isFinite(durationSec) || durationSec <= 0) {
      throw new Error('activateShield: durationSec must be a positive finite number');
    }
    this.shieldEndsAt = this.mergeTimedEnd(this.shieldEndsAt, durationSec);
  }

  /** «Ускоритель»: ×1,3 к множителю скорости (GDD), на время durationSec. */
  activateSpeedBooster(durationSec: number = BOOSTER_EFFECT_DURATION_SEC): void {
    this.assertNotTerminalForBoosterAction('activateSpeedBooster');
    if (!Number.isFinite(durationSec) || durationSec <= 0) {
      throw new Error('activateSpeedBooster: durationSec must be a positive finite number');
    }
    this.speedEndsAt = this.mergeTimedEnd(this.speedEndsAt, durationSec);
  }

  /** «Уменьшение размера»: множитель хитбокса см. {@link BOOSTER_SHRINK_HITBOX_MULTIPLIER}. */
  activateResizeShrink(durationSec: number = BOOSTER_EFFECT_DURATION_SEC): void {
    this.assertNotTerminalForBoosterAction('activateResizeShrink');
    if (!Number.isFinite(durationSec) || durationSec <= 0) {
      throw new Error('activateResizeShrink: durationSec must be a positive finite number');
    }
    this.shrinkEndsAt = this.mergeTimedEnd(this.shrinkEndsAt, durationSec);
  }

  /** «Доп. жизни»: каждый заряд поглощает одно столкновение без strike. */
  addExtraLifeCharges(count: number = 1): void {
    this.assertNotTerminalForBoosterAction('addExtraLifeCharges');
    if (!Number.isInteger(count) || count <= 0) {
      throw new Error('addExtraLifeCharges: count must be a positive integer');
    }
    this.extraLifeCharges += count;
  }

  /**
   * Столкновение с препятствием, которое **по правилам симуляции** должно ударить курьера.
   * Щит и доп. жизнь поглощают удар без роста strikes; иначе — доменный счётчик к мини-игре.
   */
  registerObstacleCollision(): ObstacleCollisionReport {
    if (this.isShieldActive()) {
      return { blockedByShield: true, consumedExtraLife: false, openedMinigame: false };
    }
    if (this.extraLifeCharges > 0) {
      this.extraLifeCharges -= 1;
      return { blockedByShield: false, consumedExtraLife: true, openedMinigame: false };
    }
    const r = applyCountedObstacleCollision(this.deliveryRun);
    this.deliveryRun = r.state;
    return { blockedByShield: false, consumedExtraLife: false, openedMinigame: r.openedMinigame };
  }

  resolveMinigameWin(): void {
    this.deliveryRun = resolveMinigameWin(this.deliveryRun);
  }

  resolveMinigameLoss(): void {
    this.deliveryRun = resolveMinigameLoss(this.deliveryRun);
  }

  abort(): void {
    this.deliveryRun = abortDeliveryRun(this.deliveryRun);
  }

  completeLevel(): void {
    this.deliveryRun = completeDeliveryRun(this.deliveryRun);
  }
}
