import { NavLink, Outlet, useLocation } from 'react-router-dom';
import type { CSSProperties } from 'react';
import { t } from '../../i18n';
import hotbarBackground from '../../infrastructure/assets/Images/hotbarBackground.png';
import mapIcon from '../../infrastructure/assets/Images/mapIcon.png';
import deliveryIcon from '../../infrastructure/assets/Images/deliveryIcon.png';
import rewardsIcon from '../../infrastructure/assets/Images/rewardsIcon.png';
import coinCountBackground from '../../infrastructure/assets/Images/coinCountBackground_default.png';
import coinIcon from '../../infrastructure/assets/Images/coinIcon.png';

const barWrap: CSSProperties = {
  flexShrink: 0,
  paddingBottom: 'env(safe-area-inset-bottom)',
  backgroundImage: `url(${hotbarBackground})`,
  backgroundSize: '100% 100%',
  backgroundRepeat: 'no-repeat',
  backgroundPosition: 'center top',
};

const barInner: CSSProperties = {
  display: 'grid',
  gridTemplateColumns: '1fr 1fr 1fr',
  gap: 4,
  padding: '10px 12px 14px',
  maxWidth: 520,
  margin: '0 auto',
};

const linkBase: CSSProperties = {
  textDecoration: 'none',
  color: '#f6e9ff',
  borderRadius: 14,
  padding: '8px 4px',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  gap: 4,
  fontSize: 11,
  fontWeight: 700,
  border: '2px solid transparent',
};

const iconStyle: CSSProperties = {
  width: 40,
  height: 40,
  objectFit: 'contain',
};

function GameBottomNav() {
  return (
    <nav style={barWrap} aria-label={t('game.nav.aria')}>
      <div style={barInner}>
        <NavLink
          to="/game/map"
          style={({ isActive }) => ({
            ...linkBase,
            backgroundColor: isActive ? 'rgba(40, 12, 72, 0.45)' : 'transparent',
            borderColor: isActive ? '#f0c14d' : 'transparent',
          })}
        >
          <img src={mapIcon} alt="" style={iconStyle} />
          {t('game.nav.map')}
        </NavLink>
        <NavLink
          to="/game/deliveries"
          style={({ isActive }) => ({
            ...linkBase,
            backgroundColor: isActive ? 'rgba(40, 12, 72, 0.45)' : 'transparent',
            borderColor: isActive ? '#f0c14d' : 'transparent',
          })}
        >
          <img src={deliveryIcon} alt="" style={iconStyle} />
          {t('game.nav.deliveries')}
        </NavLink>
        <NavLink
          to="/game/rewards"
          style={({ isActive }) => ({
            ...linkBase,
            backgroundColor: isActive ? 'rgba(40, 12, 72, 0.45)' : 'transparent',
            borderColor: isActive ? '#f0c14d' : 'transparent',
          })}
        >
          <img src={rewardsIcon} alt="" style={iconStyle} />
          {t('game.nav.rewards')}
        </NavLink>
      </div>
    </nav>
  );
}

const layoutRoot: CSSProperties = {
  minHeight: '100dvh',
  display: 'flex',
  flexDirection: 'column',
  background: '#2a0f45',
};

const outletWrap: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  position: 'relative',
};

const coinHudWrap: CSSProperties = {
  position: 'absolute',
  top: 'max(8px, env(safe-area-inset-top))',
  right: 12,
  zIndex: 20,
  pointerEvents: 'none',
};

const coinPill: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  gap: 8,
  padding: '6px 14px 6px 10px',
  minWidth: 120,
  justifyContent: 'flex-end',
  backgroundImage: `url(${coinCountBackground})`,
  backgroundSize: '100% 100%',
  color: '#fff',
  fontWeight: 800,
  fontSize: 16,
  pointerEvents: 'auto',
  filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.35))',
};

export function GameHubLayout() {
  const location = useLocation();
  const hideNav = location.pathname.startsWith('/game/character');

  return (
    <div style={layoutRoot}>
      <div style={outletWrap}>
        <Outlet />
        {hideNav ? null : (
          <div style={coinHudWrap}>
            <div style={coinPill} aria-label={t('game.map.coins')}>
              <span>1135</span>
              <img src={coinIcon} alt="" width={28} height={28} style={{ objectFit: 'contain' }} />
            </div>
          </div>
        )}
      </div>
      {hideNav ? null : <GameBottomNav />}
    </div>
  );
}
