import type { BoosterKind } from '../../domain';
import type { GameSession } from './GameSession';

/** Подбор бустера по GDD: сразу активировать эффект на сессии. */
export function applyBoosterPickupToSession(session: GameSession, type: BoosterKind): void {
  switch (type) {
    case 'shield':
      session.activateShield();
      break;
    case 'speed':
      session.activateSpeedBooster();
      break;
    case 'resize_shrink':
      session.activateResizeShrink();
      break;
    case 'extra_life':
      session.addExtraLifeCharges(1);
      break;
    default: {
      const _exhaustive: never = type;
      throw new Error(`applyBoosterPickupToSession: unknown booster type ${String(_exhaustive)}`);
    }
  }
}
