import { isTerminal } from '../../domain';
import type { GameSession } from './GameSession';

/**
 * Фаза, выводимая из доменного состояния сессии (без UI).
 * «Брифинг» и т.п. до старта `GameSession` остаются вне этой функции.
 */
export type DerivedGameplayPhase = 'flying' | 'minigame_required' | 'finished';

export function deriveGameplayPhase(session: GameSession): DerivedGameplayPhase {
  const run = session.getDeliveryRun();
  if (isTerminal(run)) {
    return 'finished';
  }
  if (run.kind === 'minigame_required') {
    return 'minigame_required';
  }
  return 'flying';
}
