import type { LevelDefinition } from '../../domain';

/**
 * Конец маршрута по оси `s` уровня: максимальный `toS` среди сегментов.
 */
export function getLevelRouteEndS(level: LevelDefinition): number {
  let maxTo = 0;
  for (const seg of level.segments) {
    if (Number.isFinite(seg.toS) && seg.toS > maxTo) {
      maxTo = seg.toS;
    }
  }
  return maxTo;
}
