import { Link, useNavigate, useParams } from 'react-router-dom';
import { getGiantDisplayName, getGiantOrderText, DEV_FLIGHT_LEVEL } from '../../content';
import { t } from '../../i18n';
import type { MissionRef } from '../../domain';
import { isGiantId, validateMissionRef } from '../../domain';

function parseOrderIndex(raw: string | undefined): number | null {
  if (raw === undefined || raw === '') {
    return null;
  }
  const n = Number.parseInt(raw, 10);
  return Number.isInteger(n) ? n : null;
}

export function MissionBriefScreen() {
  const { giantId: giantIdParam, orderIndex: orderIndexParam } = useParams<{
    giantId: string;
    orderIndex: string;
  }>();
  const navigate = useNavigate();

  const giantId = giantIdParam != null && isGiantId(giantIdParam) ? giantIdParam : null;
  const orderIndex = parseOrderIndex(orderIndexParam);
  const mission: MissionRef | null =
    giantId != null && orderIndex != null ? { giantId, orderIndex } : null;
  const validation = mission != null ? validateMissionRef(mission) : { ok: false as const, errors: ['invalid'] };

  if (mission == null || !validation.ok) {
    return (
      <div style={{ padding: 24 }}>
        <p>{t('shell.mission.invalid')}</p>
        <Link to="/home">{t('shell.mission.backHome')}</Link>
      </div>
    );
  }

  const orderText = getGiantOrderText(mission);
  const clientName = getGiantDisplayName(mission.giantId);
  const canStartPrototype = mission.giantId === DEV_FLIGHT_LEVEL.giantId;

  return (
    <div style={{ padding: 24, maxWidth: 560 }}>
      <p>
        <Link to="/home">{t('shell.mission.backHome')}</Link>
      </p>
      <h1>{t('shell.mission.title')}</h1>
      <dl style={{ marginBottom: 20 }}>
        <dt style={{ fontWeight: 600 }}>{t('shell.mission.clientLabel')}</dt>
        <dd style={{ margin: '0 0 12px 0' }}>{clientName}</dd>
        <dt style={{ fontWeight: 600 }}>{t('shell.mission.orderLabel')}</dt>
        <dd style={{ margin: 0 }}>{orderText}</dd>
      </dl>
      {!canStartPrototype ? (
        <p role="status">{t('shell.mission.devLevelOnly')}</p>
      ) : null}
      <button
        type="button"
        disabled={!canStartPrototype}
        onClick={() => {
          navigate('/play', { replace: false, state: { mission } });
        }}
      >
        {t('shell.mission.start')}
      </button>
    </div>
  );
}
